var EXTRA=[{dot:"gray",j:"Arthroscopy",h:"Le lacerazioni radiali del menisco restano difficili da riparare",v:"Un editoriale di accompagnamento al consensus Delphi sulle lesioni radiali del menisco sottolinea perché restano tecnicamente impegnative: qualità del tessuto, allineamento e grado di artrosi pesano nella decisione fra riparare o asportare, specie nelle lesioni croniche degenerative.",pmid:'42701894',doi:'10.1002/arj.70468',temi:["menisco","lacerazione radiale","tecnica chirurgica"]},{dot:"gray",j:"Orthopaedic Surgery",h:"Un nuovo allineamento per la protesi usa il ginocchio sano come riferimento",v:"Un gruppo cinese propone una strategia di allineamento cinematico che usa il ginocchio controlaterale sano come riferimento nella protesi totale, confrontandola con l'allineamento meccanico e cinematico classico su modelli agli elementi finiti e in una piccola casistica clinica.",pmid:'42710954',doi:'10.1111/os.70417',temi:["protesi totale","allineamento cinematico","biomeccanica"]},{dot:"gray",j:"Chinese Journal of Reparative and Reconstructive Surgery",h:"In Cina, gli osteofiti tibiali postero-mediali cambiano il bilanciamento robotico",v:"In una casistica cinese di protesi robot-assistite, gli osteofiti tibiali postero-mediali di dimensioni maggiori alterano gli spazi articolari pianificati dal robot, suggerendo un aggiustamento preoperatorio per gli osteofiti più grandi.",pmid:'42642193',doi:'10.7507/1002-1892.202602049',temi:["protesi robotica","osteofiti","chirurgia asiatica"]},{dot:"gray",j:"Arthroscopy Techniques",h:"Una fissazione a doppio bottone corticale per l'MPFL a doppio fascio",v:"Nota tecnica cinese su una fissazione mininvasiva con bottoni corticali regolabili su entrambi i lati per la ricostruzione anatomica a doppio fascio del legamento femoro-rotuleo mediale, alternativa alle ancore e alle viti a interferenza.",pmid:'42701584',doi:'10.1002/atn2.70242',temi:["mpfl","instabilità rotulea","tecnica chirurgica"]},{dot:"gray",j:"Clinical Case Reports",h:"Un caso di continuità clinica del crociato in un'adolescente, senza chirurgia",v:"Caso singolo di continuità clinica e alla risonanza del legamento crociato anteriore dopo una rottura funzionalmente completa in un'atleta adolescente, trattata senza intervento chirurgico.",pmid:'42699145',doi:'10.1002/ccr3.71743',temi:["lca adolescente","guarigione spontanea","caso clinico"]},{dot:"gray",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Chi ha già usato oppioidi rischia di più dopo la ricostruzione del LCA",v:"In un protocollo di analgesia a risparmio di oppioidi dopo ricostruzione del LCA, l'uso pregresso di oppioidi — più della resilienza percepita o dell'ansia — predice dolore e consumo di farmaci nel primo mese.",pmid:'42707200',doi:'10.1002/ars2.70066',temi:["lca","gestione del dolore","oppioidi"]},{dot:"gray",j:"Journal of Orthopaedic Surgery (Hong Kong)",h:"La nefropatia diabetica pesa sulle complicanze della protesi di ginocchio",v:"Analisi con abbinamento per propensione su un grande registro americano di ricoveri: la nefropatia diabetica si associa a più complicanze chirurgiche e mediche dopo protesi totale di ginocchio, e a degenze più lunghe e costose.",pmid:'42710867',doi:'10.1177/10225536261488192',temi:["protesi totale","diabete","complicanze"]},{dot:"gray",j:"Journal of Experimental Orthopaedics",h:"Menischi stampati in 3D: dove siamo nella ricerca preclinica",v:"Revisione sistematica di studi preclinici su modelli animali sugli scaffold meniscali stampati in 3D: risultati promettenti su integrazione e preservazione della cartilagine, ma ancora lontani dall'uso clinico per l'eterogeneità dei materiali e dei protocolli.",pmid:'42708084',doi:'10.1002/jeo2.70898',temi:["menisco","bioingegneria","ricerca preclinica"]},{dot:"gray",j:"Journal of Sport and Health Science",h:"Allenarsi alla forza per tutta la vita non modifica l'artrosi, ma aiuta a conviverci",v:"Una rassegna sostiene che l'allenamento di forza praticato per tutta la vita costruisce una riserva funzionale nel ginocchio artrosico, senza modificare il decorso strutturale della malattia — la forza come cuscinetto funzionale, non come cura.",pmid:'42705457',doi:'10.1016/j.jshs.2026.101094',temi:["artrosi","allenamento di forza","riserva funzionale"]},{dot:"gray",j:"Journal of Neurophysiology",h:"Il crociato non è solo un legamento: la prospettiva neurofisiologica",v:"Una rassegna propone di guardare alla lesione del legamento crociato anteriore anche come a un evento neurofisiologico, con ripercussioni sul controllo corticale e spinale del movimento che vanno oltre la sola struttura meccanica lesa.",pmid:'42709462',doi:'10.1152/jn.00248.2026',temi:["lca","neurofisiologia","controllo motorio"]},{dot:"gray",j:"Orthopedic Research and Reviews",h:"Nella protesi bilaterale in due tempi, il secondo intervento non fa più male",v:"Un'analisi retrospettiva sul dolore postoperatorio nelle 72 ore dopo protesi bilaterale di ginocchio eseguita in due tempi separati trova che il secondo intervento non è più doloroso del primo.",pmid:'42707397',doi:'10.2147/ORR.S551234',temi:["protesi totale","dolore postoperatorio","chirurgia bilaterale"]},{dot:"gray",j:"The Journal of Pain",h:"Come vivono nel tempo gli adolescenti con un dolore al ginocchio non traumatico",v:"Uno studio qualitativo con interviste ripetute segue come cambiano nel tempo le esperienze e le percezioni degli adolescenti con condizioni dolorose del ginocchio non legate a un trauma, per capire meglio come comunicare con loro in ambulatorio.",pmid:'42705401',doi:'10.1016/j.jpain.2026.104945',temi:["ginocchio adolescente","dolore cronico","comunicazione medico-paziente"]},{dot:"gray",j:"Arthroplasty Today",h:"Chirurghi e pazienti obesi non sempre hanno le stesse priorità sulla protesi",v:"Un gruppo di lavoro con chirurghi e pazienti con alto indice di massa corporea individua tre aree prioritarie per migliorare l'assistenza nella protesi articolare: ottimizzazione preoperatoria, formazione dei chirurghi, decisione condivisa.",pmid:'42699140',doi:'10.1016/j.artd.2026.102127',temi:["protesi totale","obesità","decisione condivisa"]}];
var SCOPERTE=[{t:"Dalla Cina, l'intelligenza artificiale che integra RM, radiografia e cammino per la diagnosi precoce di artrosi",v:"Una rassegna cinese descrive come la fusione multimodale con apprendimento profondo — risonanza, radiografia, dati clinici, analisi del cammino — possa cogliere i segnali precoci dell'artrosi di ginocchio prima che siano visibili su una singola immagine, anche se gli stessi autori avvertono che serve ancora una validazione multicentrica prima dell'uso clinico.",pmid:'42656119',doi:'10.7507/1001-5515.202601026',temi:["intelligenza artificiale","diagnostica per immagini","mondo orientale"]},{t:"Una mappa bibliometrica di tutta la ricerca sul bilanciamento dei tessuti molli nella protesi robotica",v:"Un'analisi bibliometrica di 350 articoli (2015-2026) mostra come la ricerca sul bilanciamento dinamico degli spazi articolari nella protesi robotica si sia spostata dalla semplice navigazione computer-assistita verso l'allineamento funzionale e la valutazione cinematica, con Stati Uniti e il gruppo di Lione (Plaskos, Lustig, Batailler) come poli trainanti — e i sensori integrati con intelligenza artificiale indicati come prossima frontiera.",pmid:'42611399',doi:'10.1007/s11701-026-03844-1',temi:["bibliometria","protesi robotica","intelligenza artificiale"]}];
var SOC={"1": {"video": "Due modi diversi di far vedere l'osso a un robot chirurgico per la protesi di ginocchio: uno con una TC fatta prima dell'intervento, uno senza immagini. In un confronto retrospettivo su quasi trecento protesi, il primo ottiene un allineamento più preciso e un recupero funzionale leggermente migliore — oltre la soglia considerata clinicamente rilevante. Su un altro punteggio la differenza c'è, ma è così piccola che probabilmente il paziente non la percepirebbe. Non è uno studio randomizzato, e non dice quali marche siano state confrontate: un primo tassello, non una sentenza definitiva su quale filosofia di robot sia la migliore."}, "2": {"video": "Nello stesso grande centro americano dove opera Volker Musahl, un'analisi di ventisei anni e quasi ottomila ricostruzioni del legamento crociato anteriore mostra un cambiamento netto: il tendine quadricipitale, poco usato all'inizio, è salito con continuità dal 2016, mentre l'hamstring è sceso in modo costante, anno dopo anno, per tutto il periodo. Anche in revisione il quadricipite cresce mentre l'allograft cala. È la tendenza di un solo centro, per quanto ampio e con dieci chirurghi diversi: non dimostra che un innesto sia clinicamente superiore, ma conferma che il campo si sta muovendo dove l'innesto di scelta è già il tendine quadricipitale."}, "3": {"video": "Otto chirurghi di sei paesi europei hanno scritto una guida tecnica sugli errori più comuni quando si comincia a usare VELYS, il sistema robotico senza immagini per la protesi di ginocchio: posizionamento dei pin, controllo dei punti di repere ossei, acquisizione dei riferimenti anatomici, con i segnali intraoperatori che permettono di riconoscere l'errore prima di eseguire le resezioni. È un testo di opinione basata sull'esperienza clinica, livello cinque, senza numeri su quanto questi errori siano davvero frequenti né un confronto con altri sistemi robotici — ma è materiale operativo diretto per chi lavora con questa piattaforma."}, "4": {"video": "Un'analisi retrospettiva dei dati intraoperatori di un robot chirurgico in 241 protesi di ginocchio con conservazione del crociato posteriore mostra che lasciare troppo spessore osseo su un lato del femore — il cosiddetto overstuffing del condilo laterale — cambia il modo in cui la rotula scorre durante l'intervento e come si inclina dopo. I dati vengono da un solo sistema robotico, diverso da VELYS, e l'abstract non riporta i valori numerici precisi delle associazioni: resta un principio tecnico trasferibile a qualunque piattaforma robotica con conservazione del crociato, non una regola quantificata sulla tua."}, "5": {"video": "Uno studio giapponese su 40 osteotomie tibiali alte a cuneo di chiusura guarda a un dettaglio spesso trascurato: la differenza fra la radiografia del ginocchio fatta in piedi e quella fatta da sdraiati, prima dell'intervento. Quando questa differenza è ampia, la correzione ottenuta si scosta da quella pianificata — in un senso o nell'altro a seconda di quale radiografia il chirurgo usa come riferimento — con una correlazione statisticamente confermata anche dopo aggiustamento per altri fattori. È uno studio piccolo, su un solo centro e una sola tecnica di osteotomia: un promemoria pratico per la pianificazione, non una regola valida per ogni caso."}, "6": {"video": "Una revisione sistematica di diciassette studi comparativi, milleduecentosettantuno ginocchia in tutto, si chiede se aggiungere un trattamento artroscopico — su cartilagine o menisco — durante un'osteotomia tibiale alta valgizzante porti un vantaggio in più rispetto alla sola correzione dell'asse. L'aspetto della cartilagine può migliorare quando si guarda di nuovo con l'artroscopio, ma nessuno dei gesti associati, centralizzazione meniscale compresa, dimostra un beneficio clinico costante sui punteggi funzionali dei pazienti. Gli studi inclusi erano troppo diversi fra loro per essere sommati in un calcolo statistico unico: la conclusione è una tendenza descrittiva, non una risposta definitiva — ma è un secondo segnale, da un angolo diverso, che aggiungere la centralizzazione meniscale non risolve da solo il problema dell'estrusione residua."}, "7": {"video": "Uno studio dell'Hospital for Special Surgery su centotrenta pazienti operati di sutura meniscale confronta chi ha meno di quarant'anni con chi ne ha di più: a due anni, nessuna differenza significativa nel punteggio IKDC, nel rientro allo sport o nel tasso di fallimento della sutura, sia nella riparazione isolata sia in quella associata alla ricostruzione del legamento crociato anteriore. Oltre l'ottanta per cento dei pazienti in entrambi i gruppi raggiunge la soglia minima di miglioramento clinicamente importante. Il gruppo over quaranta conta però solo trentanove pazienti, diviso in sottogruppi ancora più piccoli: un segnale incoraggiante per il colloquio con i pazienti più adulti, non ancora una dimostrazione di equivalenza su numeri così ridotti."}, "8": {"video": "Una metanalisi di trentuno studi osservazionali guarda a un fattore di rischio poco discusso per l'infezione dopo protesi articolare: una precedente artroscopia sulla stessa articolazione. Il rischio sale — odds ratio 1,33 per l'infezione complessiva, 1,38 per quella profonda — ma solo per ginocchio e spalla: per l'anca, l'artroscopia pregressa non risulta un fattore di rischio. Sono tutti studi osservazionali, e il confondimento per indicazione resta possibile, perché chi ha già avuto un'artroscopia può partire da un'articolazione già più compromessa. Resta un'informazione utile per il colloquio preoperatorio prima di una protesi di ginocchio in un paziente con una o più artroscopie pregresse sullo stesso ginocchio."}};
var SOCV={"1": {"video": {"chir": ["Uno studio retrospettivo con abbinamento per punteggio di propensione confronta, nella protesi totale di ginocchio, un sistema robotico basato su tomografia computerizzata con uno senza immagini preoperatorie.", "Duecentonovantaquattro protesi in tutto: il sistema con TC ottiene un allineamento più vicino al target pianificato — angolo anca-ginocchio-caviglia -0,22° contro -2,52° — e un punteggio funzionale KSS migliore a uno e due anni, oltre la soglia minima clinicamente importante.", "Ma su un altro punteggio, l'Oxford Knee Score, la differenza è statisticamente significativa senza superare quella soglia: gli stessi autori la considerano probabilmente non percepibile. Nessuna differenza su dolore e range di movimento. Retrospettivo, non randomizzato, e l'abstract non nomina le piattaforme."], "misto": ["Un lavoro ha confrontato due filosofie di robot chirurgico per la protesi di ginocchio: una che si basa su una TC fatta prima dell'intervento, una che non usa immagini.", "Nel confronto retrospettivo su quasi trecento protesi, il sistema con TC ottiene un posizionamento dell'impianto più preciso e un punteggio funzionale migliore dopo uno e due anni — una differenza abbastanza grande da essere considerata rilevante.", "Su un secondo punteggio la differenza è statisticamente reale ma piccola: gli stessi ricercatori dicono che probabilmente il paziente non la percepirebbe. Non è uno studio randomizzato, e non dice quali marche siano state confrontate."], "pazienti": ["Anche fra i robot usati per operare la protesi di ginocchio ci sono differenze, a seconda di come «vedono» l'osso prima di operare.", "Un confronto ha messo a paragone un sistema che usa una TC fatta prima dell'intervento con uno che non la usa: il primo ha dato un posizionamento un po' più preciso della protesi e un recupero funzionale leggermente migliore.", "Non significa che un metodo sia sbagliato: sono entrambi interventi validi e sicuri, e una delle differenze misurate era così piccola che probabilmente non si sente nella vita di tutti i giorni."]}, "linkedin": {"chir": ["Studio retrospettivo con abbinamento per propensione (181 TC-based vs 113 CT-free) su un sistema robotico per TKA semi-attivo basato su TC contro uno passivo senza immagini.", "Il gruppo TC-based ottiene KSS-Funzione migliore a 1 e 2 anni (oltre la MCID) e allineamento più vicino al target (MPTA 90,0° vs 87,8°; HKA -0,22° vs -2,52°; flessione femorale 3,22°±0,37° vs 0,15°±0,47°, p=0,001). L'OKS a 2 anni è significativo ma sotto la MCID: gli autori stessi lo giudicano di incerta rilevanza clinica.", "Retrospettivo, monocentrico, non randomizzato; l'abstract non nomina le piattaforme commerciali. Un confronto diretto fra le due filosofie di navigazione robotica che merita attenzione anche per chi usa un sistema image-free."], "misto": ["Un confronto retrospettivo fra due modi di guidare il robot chirurgico nella protesi di ginocchio: uno con TC preoperatoria, uno senza immagini.", "Su quasi 300 casi, il sistema con TC ottiene un posizionamento più vicino al target pianificato e un punteggio funzionale migliore dopo uno e due anni, oltre la soglia clinicamente rilevante.", "Una seconda differenza è statisticamente presente ma probabilmente non percepibile dal paziente, per ammissione degli stessi autori. Studio osservazionale, non uno studio randomizzato, non nomina le marche confrontate."], "pazienti": ["Anche i robot chirurgici usati per la protesi di ginocchio possono differire, a seconda di come pianificano l'intervento.", "In un confronto, il sistema che usa una TC prima dell'intervento ha dato un posizionamento leggermente più preciso e un recupero funzionale un po' migliore rispetto a quello senza immagini.", "Non è un motivo di allarme: entrambi sono metodi validi, e una delle differenze osservate era talmente piccola da non essere probabilmente percepibile."]}, "instagram": {"chir": ["🤖 Robot con TC preoperatoria vs robot senza immagini nella protesi di ginocchio: chi vince?", "In 294 protesi con abbinamento per propensione, il sistema TC-based ottiene un allineamento più vicino al target e un KSS-Funzione migliore, oltre la soglia clinicamente rilevante — su un altro punteggio la differenza è reale ma probabilmente non percepibile.", "Retrospettivo, non randomizzato, piattaforme non nominate: un primo confronto diretto fra due filosofie di navigazione robotica, non una sentenza definitiva."], "misto": ["🦿 Nella protesi robotica di ginocchio non tutti i sistemi funzionano allo stesso modo.", "Un confronto su quasi 300 casi mostra che il sistema con TC preoperatoria ottiene un posizionamento più preciso e un recupero funzionale migliore — su un altro punteggio la differenza è statisticamente presente ma piccola.", "Non uno studio randomizzato: un segnale interessante, non una conclusione definitiva su quale robot sia «migliore»."], "pazienti": ["🦵 Curiosità dalla ricerca: anche i robot per la protesi di ginocchio possono differire fra loro.", "Uno studio ha confrontato due modi diversi in cui un robot chirurgico pianifica l'intervento: uno usa una TC fatta prima, uno no. Il primo ha dato risultati leggermente migliori su alcuni aspetti.", "Nessun allarme: sono entrambi metodi sicuri, e la differenza più piccola osservata probabilmente non si sente nella vita di tutti i giorni."]}, "reel": {"chir": ["[294 protesi · propensione abbinata] Robot con TC preoperatoria contro robot senza immagini nella protesi di ginocchio.", "[KSS-F oltre la MCID · allineamento più preciso] Il sistema TC-based vince su alcuni esiti — ma su un altro la differenza è sotto la soglia rilevante.", "[Retrospettivo, non randomizzato] Le piattaforme non sono nominate nell'abstract: un primo confronto, non una sentenza."], "misto": ["[Due filosofie a confronto] TC preoperatoria o niente immagini: conta per il risultato della protesi robotica?", "[Allineamento più preciso · funzione migliore] Il sistema con TC ottiene risultati migliori su alcuni punteggi, oltre la soglia clinicamente rilevante.", "[Non tutto conta uguale] Su un altro punteggio la differenza è reale ma probabilmente non percepibile dal paziente."], "pazienti": ["[Anche i robot sono diversi fra loro] Come «vede» l'osso il robot prima di operare può fare la differenza.", "[Posizionamento più preciso] Un confronto mostra un piccolo vantaggio per il sistema che usa una TC prima dell'intervento.", "[Nessun allarme] Entrambi i metodi sono sicuri: la differenza osservata più piccola probabilmente non si sente."]}}, "2": {"video": {"chir": ["A Pittsburgh, nel centro dove opera Volker Musahl, un'analisi retrospettiva di 7657 ricostruzioni del LCA copre ventisei anni, dal 2000 al 2025.", "L'uso del tendine quadricipitale come innesto primario è salito in modo significativo dal 2016 al 2019, mentre l'hamstring è sceso in media dell'8,3% l'anno per tutto il periodo — e anche in revisione il quadricipite cresce mentre l'allograft cala.", "È la tendenza di un solo centro, per quanto grande: riflette la scuola locale, non un consenso internazionale, e non dice nulla sull'uso del rinforzo laterale accanto ai vari innesti."], "misto": ["Un grande ospedale americano ha guardato tutte le sue ricostruzioni del legamento crociato anteriore degli ultimi ventisei anni: quasi ottomila interventi.", "Il tendine quadricipitale, poco usato all'inizio, è salito con continuità dal 2016, mentre l'uso del tendine hamstring si è ridotto in modo costante per tutto il periodo, anno dopo anno.", "Racconta come è cambiata la pratica di un centro nel tempo, non dimostra che un innesto sia clinicamente superiore: la scelta dipende anche da fattori del paziente e dall'esperienza del chirurgo."], "pazienti": ["In un grande ospedale americano, l'analisi di ventisei anni di interventi sul legamento crociato anteriore mostra un cambiamento chiaro nella scelta del tendine da prelevare.", "Il tendine del muscolo quadricipite, poco usato all'inizio, oggi viene scelto sempre più spesso, mentre l'uso di un altro tendine, quello dietro il ginocchio, si è ridotto negli anni.", "Non vuol dire che un innesto sia sempre meglio di un altro: la scelta resta individuale e dipende da tanti fattori valutati caso per caso."]}, "linkedin": {"chir": ["Coorte retrospettiva, UPMC Freddie Fu Sports Medicine Center (Pittsburgh, gruppo Musahl): 7657 ricostruzioni del LCA, 2000-2025, 10 chirurghi.", "QT autoinnesto primario in aumento significativo vs BPTB (OR 1,19; p<0,01), con incremento Joinpoint 2016-2019 (p=0,03); HS primario in calo costante -8,3%/anno (p<0,01) per tutto il periodo. In revisione: QT in aumento (OR 1,15; p<0,01), allograft in calo -8,1%/anno (p<0,01).", "Dati di un solo centro, per quanto ampio e multi-chirurgo: riflette anche preferenze locali. Nessun dato sull'uso concomitante di un rinforzo extra-articolare laterale. Un riferimento diretto per chi segue la scuola di Pittsburgh su innesto quadricipitale."], "misto": ["Ventisei anni di dati su quasi ottomila ricostruzioni del crociato anteriore, nello stesso grande centro americano.", "L'innesto dal tendine del quadricipite è salito con continuità dal 2016, mentre l'hamstring è sceso in modo costante per tutto il periodo, anno dopo anno.", "È una fotografia di come cambia la pratica clinica nel tempo, non una prova di superiorità di un innesto sull'altro: la scelta resta individuale."], "pazienti": ["In un grande ospedale americano, ventisei anni di interventi sul legamento del ginocchio raccontano un cambiamento chiaro nella scelta dell'innesto.", "Il tendine del quadricipite, all'inizio poco usato, oggi è scelto sempre più spesso; l'uso di un altro tendine si è ridotto nello stesso periodo.", "Non significa che ci sia un innesto giusto per tutti: la decisione resta del chirurgo, caso per caso."]}, "instagram": {"chir": ["📈 A Pittsburgh, 26 anni e 7657 ricostruzioni del LCA raccontano un cambiamento netto nella scelta dell'innesto.", "Il tendine quadricipitale sale con continuità dal 2016 (OR 1,19 vs BPTB, p<0,01), l'hamstring scende dell'8,3% l'anno per tutto il periodo — anche in revisione il quadricipite cresce mentre l'allograft cala.", "Dati di un solo centro, per quanto ampio: una tendenza, non una dimostrazione di superiorità clinica dell'uno sull'altro innesto."], "misto": ["📊 Come sceglie l'innesto per il crociato un grande centro americano, in 26 anni di pratica.", "Il tendine del quadricipite, poco usato all'inizio, è salito con continuità dal 2016; l'hamstring è sceso in modo costante per tutto il periodo.", "Racconta un cambiamento di pratica, non stabilisce quale innesto sia clinicamente migliore: la scelta resta personalizzata."], "pazienti": ["🦵 Negli Stati Uniti cresce l'uso del tendine del quadricipite per riparare il legamento del ginocchio.", "Un grande ospedale ha guardato ventisei anni dei suoi interventi: l'innesto dal quadricipite, poco usato all'inizio, oggi viene scelto molto più spesso.", "Non vuol dire che sia sempre la scelta giusta: dipende da tanti fattori che il chirurgo valuta caso per caso."]}, "reel": {"chir": ["[7657 ricostruzioni · 26 anni · Pittsburgh] Come cambia la scelta dell'innesto per il crociato anteriore.", "[QT +, OR 1,19 p<0,01 · HS -8,3%/anno] Il tendine quadricipitale sale, l'hamstring scende, per tutto il periodo.", "[Un solo centro] Tendenza reale, non una prova di superiorità clinica di un innesto sull'altro."], "misto": ["[26 anni di dati] Un grande centro americano racconta come cambia la scelta dell'innesto per il crociato.", "[Quadricipite in salita · Hamstring in calo] Un cambiamento costante, anno dopo anno, dal 2000 al 2025.", "[Non è un verdetto] Mostra una tendenza di pratica, non quale innesto sia migliore in assoluto."], "pazienti": ["[Un cambiamento nel tempo] Come si sceglie oggi il tendine per riparare il legamento del ginocchio.", "[Quadricipite in crescita] Un grande ospedale americano lo usa sempre più spesso rispetto a 26 anni fa.", "[Nessuna regola unica] La scelta resta personalizzata, decisa dal chirurgo caso per caso."]}}, "3": {"video": {"chir": ["Otto chirurghi europei hanno scritto una guida tecnica sugli errori più comuni quando si impara a usare VELYS, il sistema robotico senza immagini per la protesi di ginocchio.", "Il punto è l'acquisizione dei riferimenti anatomici: posizionamento dei pin, controllo dei punti di repere ossei, bilanciamento degli spazi articolari — con i segnali intraoperatori che permettono di accorgersi dell'errore prima della resezione ossea.", "È una guida di livello cinque, opinione di esperti: nessun numero su quanto questi errori siano frequenti, nessun confronto con altri sistemi robotici."], "misto": ["Alcuni chirurghi esperti hanno messo per iscritto gli errori più comuni di chi comincia a usare un particolare sistema robotico per la protesi di ginocchio, quello senza immagini VELYS.", "Spiegano come riconoscere in tempo un posizionamento sbagliato dei riferimenti sull'osso, prima che diventi un taglio osseo eseguito nel punto sbagliato.", "È un testo di esperienza pratica, non uno studio con pazienti e statistiche: utile, ma non misura quanto questi accorgimenti riducano davvero gli errori."], "pazienti": ["Anche i robot chirurgici hanno bisogno di essere guidati bene: un gruppo di chirurghi ha scritto una guida su come farlo con un sistema robotico usato per la protesi di ginocchio.", "Spiegano quali piccoli errori tecnici evitare, così che il robot lavori sempre sui punti di riferimento giusti sull'osso.", "È un promemoria per i medici, non uno studio su pazienti: non dice quanto cambi in pratica il risultato dell'intervento."]}, "linkedin": {"chir": ["Guida tecnica (8 autori, 6 paesi) su landmarking e gap balance nella TKA robot-assistita con sistema image-free VELYS.", "Focus su posizionamento dei pin, checkpoint dei repere ossei, acquisizione dei riferimenti anatomici, con i segnali intraoperatori per riconoscere l'errore prima della resezione ossea.", "Livello V, opinione di esperti: nessun dato quantitativo su frequenza degli errori né confronto con altri sistemi robotici. Materiale operativo diretto per chi opera con questa piattaforma."], "misto": ["Un gruppo di chirurghi europei ha scritto una guida sugli errori tecnici più comuni con un sistema robotico senza immagini per la protesi di ginocchio.", "Spiega come riconoscere in tempo, in sala, un posizionamento impreciso dei riferimenti sull'osso, prima che porti a una resezione ossea sbagliata.", "È esperienza clinica, non uno studio quantitativo: non misura quanto questi accorgimenti riducano davvero gli errori nella pratica."], "pazienti": ["Una guida tecnica scritta da chirurghi esperti su come usare bene un sistema robotico per la protesi di ginocchio.", "Spiega quali errori evitare nel posizionamento dei riferimenti sull'osso, per assicurarsi che il robot lavori sempre nel modo corretto.", "È un testo per i medici: aiuta a capire quanta attenzione tecnica richiede questo tipo di chirurgia, non cambia le indicazioni all'intervento."]}, "instagram": {"chir": ["🤖 Una guida tecnica su come evitare gli errori di puntamento con il sistema robotico senza immagini VELYS.", "Otto chirurghi europei descrivono i punti critici — pin, repere ossei, acquisizione dei riferimenti — e come riconoscerli prima della resezione ossea.", "Livello V, opinione di esperti: nessun numero sulla frequenza degli errori, nessun confronto con altri robot."], "misto": ["🦾 Anche un robot chirurgico ha bisogno di essere guidato bene: ecco una guida su come farlo.", "Alcuni chirurghi spiegano gli errori più comuni all'inizio, e come accorgersene prima che diventino un taglio osseo sbagliato.", "Non è uno studio con numeri: è esperienza clinica messa per iscritto."], "pazienti": ["🦵 Curiosità dalla sala operatoria: anche i robot chirurgici richiedono attenzione da parte del medico che li usa.", "Una guida scritta da esperti spiega come evitare piccoli errori tecnici con un sistema robotico per la protesi di ginocchio.", "Un promemoria per i chirurghi, non uno studio su pazienti."]}, "reel": {"chir": ["[8 chirurghi · 6 paesi] Guida tecnica su landmarking e gap balance con VELYS.", "[Pin · repere ossei · riferimenti] I punti critici da controllare prima della resezione ossea.", "[Livello V] Opinione di esperti, nessun dato quantitativo — ma materiale operativo diretto."], "misto": ["[Come si guida un robot chirurgico] Una guida sugli errori tecnici più comuni con VELYS.", "[Riconoscere in tempo] I segnali che dicono che qualcosa non va, prima della resezione ossea.", "[Esperienza, non statistica] Nessun numero su quanto siano frequenti questi errori."], "pazienti": ["[Anche i robot vanno guidati bene] Una guida tecnica per i chirurghi che usano un robot per la protesi.", "[Attenzione ai dettagli] Piccoli errori tecnici da evitare nel posizionamento dei riferimenti.", "[Per i medici, non per i pazienti] Non cambia le indicazioni all'intervento."]}}, "4": {"video": {"chir": ["In 241 protesi robot-assistite con conservazione del crociato posteriore, un'analisi retrospettiva dei dati intraoperatori guarda al rapporto fra allineamento coronale e movimento della rotula.", "Un condilo femorale laterale lasciato più spesso del previsto — un angolo nativo più valgo, una correzione maggiore, una resezione più sottile — si associa a un peggior scorrimento della rotula durante l'intervento e a una maggiore inclinazione laterale della rotula dopo l'intervento.", "L'abstract non riporta i valori numerici precisi delle associazioni, e i dati vengono da un solo sistema robotico, diverso da VELYS: un principio generale, non una regola quantificata sulla tua piattaforma."], "misto": ["Uno studio ha analizzato i dati registrati da un robot chirurgico in 241 protesi di ginocchio, guardando a come l'allineamento dell'osso influenza il movimento della rotula.", "Quando resta troppo spessore osseo su un lato del femore, la rotula scorre peggio durante l'intervento e tende a inclinarsi di più verso l'esterno dopo l'operazione.", "È un'osservazione su dati già raccolti per pianificare l'intervento, non uno studio randomizzato: mostra un'associazione utile per i chirurghi, non un obbligo per il paziente."], "pazienti": ["Un piccolo dettaglio tecnico nella protesi di ginocchio può influenzare come si muove la rotula dopo l'intervento, secondo un nuovo studio.", "Quando l'osso viene tagliato in modo leggermente diverso da un lato del ginocchio, la rotula può scorrere in modo meno regolare.", "È un'informazione tecnica che aiuta i chirurghi a perfezionare la pianificazione dell'intervento: non cambia le indicazioni generali alla protesi di ginocchio."]}, "linkedin": {"chir": ["Analisi retrospettiva dei dati robotici MAKO in 241 TKA con conservazione del crociato: allineamento coronale, overstuffing del condilo distale laterale e tracking rotuleo.", "Overstuffing laterale (angolo nativo più valgo, ΔLDFA maggiore, resezione più sottile) associato a maggiore necessità di release del retinacolo laterale e a maggiore inclinazione rotulea postoperatoria. Direzione ed effetto significativi, ma valori numerici precisi non riportati nell'abstract.", "Dati di una sola piattaforma robotica (MAKO), non VELYS; correlazioni osservazionali su dati intraoperatori, non uno studio randomizzato. Il principio — allineamento coronale e resezione condilare condizionano il tracking rotuleo — vale per qualunque sistema robotico con conservazione del crociato."], "misto": ["Uno studio sui dati di un robot chirurgico in 241 protesi di ginocchio mostra un legame fra allineamento osseo e movimento della rotula.", "Lasciare troppo spessore osseo su un lato del femore cambia il modo in cui la rotula scorre durante e dopo l'intervento.", "Osservazione su dati già raccolti, non uno studio randomizzato: un'indicazione tecnica utile per i chirurghi, da un sistema robotico diverso da VELYS."], "pazienti": ["Un dettaglio tecnico della protesi di ginocchio può influenzare il movimento della rotula dopo l'intervento, secondo un nuovo studio.", "Il modo in cui viene tagliato l'osso da un lato del ginocchio può cambiare come la rotula scorre nel tempo.", "Un'informazione utile per i chirurghi nella pianificazione, non un motivo di preoccupazione per chi deve operarsi."]}, "instagram": {"chir": ["🦴 In 241 protesi robot-assistite, il sovradimensionamento del condilo laterale peggiora il tracking rotuleo.", "Un angolo nativo più valgo, una correzione maggiore o una resezione più sottile del condilo laterale aumentano il rischio di release del retinacolo e di inclinazione rotulea postoperatoria.", "Dati di un solo sistema robotico (MAKO), non VELYS; effetti e IC precisi non riportati nell'abstract — un principio generale, non un numero da citare."], "misto": ["🦵 Come l'allineamento del ginocchio durante la protesi influenza il movimento della rotula.", "In 241 casi analizzati, lasciare troppo spessore osseo su un lato del femore cambia come scorre la rotula durante e dopo l'intervento.", "Osservazione su dati robotici già raccolti, non uno studio randomizzato: un segnale tecnico, non una regola assoluta."], "pazienti": ["🦿 Anche piccoli dettagli tecnici della protesi possono influenzare il movimento della rotula, secondo la ricerca.", "Uno studio mostra che il modo in cui l'osso viene tagliato da un lato del ginocchio può cambiare come scorre la rotula.", "Un'informazione per i chirurghi che pianificano l'intervento, non un motivo di allarme per il paziente."]}, "reel": {"chir": ["[241 TKA robot-assistite] Overstuffing del condilo laterale e tracking rotuleo, dati MAKO.", "[Più valgo · resezione sottile] Aumentano il rischio di release del retinacolo e inclinazione rotulea.", "[Effetti non quantificati] Dati di un solo sistema robotico, diverso da VELYS."], "misto": ["[Allineamento e rotula] Come un dettaglio del taglio osseo cambia il movimento della rotula.", "[241 casi analizzati] Troppo spessore osseo da un lato peggiora lo scorrimento rotuleo.", "[Osservazionale] Un segnale tecnico da un sistema robotico, non una regola assoluta."], "pazienti": ["[Un dettaglio che conta] Il taglio osseo durante la protesi può influenzare il movimento della rotula.", "[Per i chirurghi] Un'informazione tecnica utile nella pianificazione dell'intervento.", "[Nessun allarme] Non cambia le indicazioni generali alla protesi di ginocchio."]}}, "5": {"video": {"chir": ["In 40 osteotomie tibiali alte a cuneo di chiusura, uno studio giapponese guarda a un dettaglio spesso trascurato della pianificazione: la differenza fra la radiografia fatta in piedi e quella fatta da sdraiati.", "Quando questa differenza è ampia, la correzione ottenuta si scosta da quella pianificata — in un senso se si usa la radiografia da sdraiati come riferimento, nell'altro se si usa quella in piedi — con una correlazione statisticamente significativa confermata anche all'analisi multivariabile.", "Studio retrospettivo su soli quaranta pazienti, un solo centro, riguarda la tecnica a cuneo di chiusura: un segnale utile per la pianificazione, non una regola valida per ogni tecnica di osteotomia."], "misto": ["Un lavoro giapponese guarda a un dettaglio della radiografia che può cambiare il risultato di un'osteotomia correttiva del ginocchio.", "Quando l'articolazione appare molto diversa in piedi rispetto a sdraiati prima dell'intervento, la correzione finale tende a scostarsi da quella programmata, in una direzione o nell'altra a seconda di quale radiografia si usa per pianificare.", "È uno studio piccolo, su una sola tecnica di osteotomia e un solo centro: un segnale utile, non una regola valida per ogni caso."], "pazienti": ["Uno studio ha mostrato che, prima di un intervento di correzione dell'asse del ginocchio, anche la posizione durante la radiografia può fare la differenza.", "Se il ginocchio appare molto diverso quando il paziente è in piedi rispetto a quando è sdraiato, il chirurgo può prevedere meglio quanto sarà precisa la correzione ottenuta.", "È un dettaglio tecnico che riguarda la pianificazione dell'intervento da parte del chirurgo: non richiede nulla di diverso da parte del paziente."]}, "linkedin": {"chir": ["Coorte retrospettiva monocentrica (40 ginocchia) su predittori preoperatori del cambiamento di JLCA dopo osteotomia tibiale alta a cuneo di chiusura (CWHTO).", "La differenza preoperatoria fra JLCA in carico e supina (dJLCA) correla con il cambiamento postoperatorio calcolato da supina (r=0,52; p=0,001) e da carico (r=-0,43; p=0,007), confermata all'analisi multivariabile (r=0,51 e r=-0,49; p=0,006/0,008).", "Livello IV, monocentrico, solo tecnica a cuneo di chiusura: un promemoria pratico sulla scelta della radiografia di riferimento in fase di pianificazione, non una regola universale."], "misto": ["Un lavoro su 40 ginocchia collega un dettaglio della radiografia preoperatoria al risultato di un'osteotomia correttiva.", "Quando l'articolazione appare molto diversa in piedi rispetto a sdraiati, la correzione finale tende a scostarsi da quella programmata.", "Studio piccolo e monocentrico, su una sola tecnica di osteotomia: un'indicazione utile, non una regola generale."], "pazienti": ["Un dettaglio della radiografia può aiutare a prevedere meglio il risultato di un'osteotomia correttiva del ginocchio, secondo un nuovo studio.", "Quando il ginocchio appare diverso in piedi rispetto a sdraiati, il chirurgo può regolare meglio la pianificazione dell'intervento.", "Riguarda la parte tecnica della pianificazione fatta dal chirurgo, non richiede nulla in più da parte del paziente."]}, "instagram": {"chir": ["📐 In piedi o sdraiati: la posizione durante la radiografia conta prima di un'osteotomia del ginocchio.", "In 40 ginocchia, la differenza preoperatoria fra JLCA in carico e supina predice lo scostamento della correzione ottenuta (r fino a 0,52, p=0,001).", "Studio piccolo, monocentrico, solo tecnica a cuneo di chiusura: un segnale utile per la pianificazione."], "misto": ["🦵 Un dettaglio della radiografia che può cambiare il risultato di un'osteotomia del ginocchio.", "Quando l'articolazione appare molto diversa in piedi rispetto a sdraiati, la correzione finale può scostarsi da quella programmata.", "Studio piccolo su una sola tecnica: un'indicazione utile, non una regola per tutti i casi."], "pazienti": ["🩻 Anche la posizione durante la radiografia può contare, prima di un intervento di correzione del ginocchio.", "Uno studio mostra che confrontare la radiografia in piedi e da sdraiati aiuta il chirurgo a pianificare meglio la correzione.", "Un dettaglio tecnico per il chirurgo, non qualcosa che richiede un'azione diversa da parte del paziente."]}, "reel": {"chir": ["[40 ginocchia · CWHTO] La differenza fra radiografia in piedi e supina predice la correzione.", "[r=0,52, p=0,001] Confermata anche all'analisi multivariabile.", "[Livello IV, monocentrico] Un segnale per la pianificazione, non una regola universale."], "misto": ["[In piedi vs sdraiati] Un dettaglio della radiografia che conta per l'osteotomia del ginocchio.", "[40 casi analizzati] Una differenza ampia predice uno scostamento dalla correzione pianificata.", "[Studio piccolo] Un'indicazione utile, non una regola per ogni tecnica."], "pazienti": ["[Un dettaglio tecnico] Anche la posizione in radiografia può aiutare a pianificare meglio l'intervento.", "[Per il chirurgo] Un modo in più per prevedere il risultato dell'osteotomia.", "[Nessuna azione richiesta] Riguarda solo la pianificazione da parte del medico."]}}, "6": {"video": {"chir": ["Una revisione sistematica di diciassette studi comparativi, milleduecentosettantuno ginocchia in tutto, chiede se aggiungere un trattamento artroscopico all'osteotomia tibiale alta valgizzante porti un beneficio in più.", "Microfratture, microforature, abrasione, meniscectomia, centralizzazione meniscale: l'aspetto della cartilagine migliora in alcuni casi alla seconda artroscopia, ma nessuno di questi gesti dimostra un beneficio clinico costante sui punteggi funzionali rispetto alla sola osteotomia.", "L'eterogeneità degli studi ha impedito una vera metanalisi: la sintesi è descrittiva, non un numero aggregato definitivo."], "misto": ["Una revisione di diciassette studi si chiede se, durante un'osteotomia correttiva del ginocchio, valga la pena aggiungere anche un trattamento artroscopico di cartilagine o menisco.", "L'aspetto della cartilagine può migliorare quando si guarda di nuovo con l'artroscopio, ma i punteggi clinici dei pazienti non migliorano in modo costante rispetto alla sola osteotomia.", "Gli studi inclusi erano troppo diversi fra loro per essere sommati in un unico calcolo: una tendenza descrittiva, non una risposta definitiva."], "pazienti": ["Una revisione della letteratura ha guardato se, durante l'operazione per correggere l'asse del ginocchio, aggiungere un trattamento su cartilagine o menisco porti un vantaggio in più.", "Il risultato non è chiaramente a favore né contro: qualcosa migliora dentro l'articolazione, ma i pazienti non stanno sempre meglio in modo evidente rispetto a chi ha fatto solo la correzione dell'asse.", "La scelta di aggiungere o meno questo gesto resta una valutazione del chirurgo caso per caso, non una regola generale."]}, "linkedin": {"chir": ["Revisione sistematica (MEDLINE/Embase/CENTRAL, 17 studi comparativi, 1271 ginocchia) su HTO valgizzante ± trattamento artroscopico di cartilagine/menisco.", "Nessun gesto associato (microfrattura, microforatura, abrasione, meniscectomia, centralizzazione) mostra un beneficio clinico aggiuntivo costante su PROM, KSS o allineamento, nonostante un miglioramento dell'aspetto cartilagineo alla seconda artroscopia in alcuni casi. Eterogeneità troppo alta per una metanalisi: sintesi descrittiva.", "Rilevante per T2b: la centralizzazione meniscale, qui aggiunta all'HTO, non mostra beneficio costante — un secondo segnale nella stessa direzione già visto sulla sutura transtibiale della radice."], "misto": ["Una revisione di 17 studi comparativi (1271 ginocchia) chiede se aggiungere un gesto artroscopico all'osteotomia correttiva del ginocchio porti un vantaggio in più.", "L'aspetto della cartilagine può migliorare, ma i punteggi clinici dei pazienti non migliorano in modo costante rispetto alla sola osteotomia.", "Gli studi erano troppo eterogenei per un calcolo statistico unico: una tendenza descrittiva, non una conclusione definitiva."], "pazienti": ["Una revisione della letteratura si chiede se aggiungere un trattamento su cartilagine o menisco, durante la correzione dell'asse del ginocchio, porti un beneficio in più.", "Qualcosa migliora dentro l'articolazione, ma non sempre il paziente sta meglio in modo evidente rispetto a chi ha fatto solo la correzione.", "La decisione resta del chirurgo, caso per caso, non una regola generale valida per tutti."]}, "instagram": {"chir": ["🔬 17 studi, 1271 ginocchia: aggiungere l'artroscopia all'osteotomia porta davvero un vantaggio in più?", "Microfratture, meniscectomia, centralizzazione: l'aspetto della cartilagine migliora in alcuni casi, ma nessun gesto dimostra un beneficio clinico costante.", "Eterogeneità troppo alta per una metanalisi vera: una sintesi descrittiva, non un numero definitivo."], "misto": ["🦵 Serve davvero fare l'artroscopia insieme all'osteotomia del ginocchio?", "Una revisione di 17 studi mostra che l'aspetto della cartilagine può migliorare, ma i pazienti non stanno sempre meglio in modo evidente.", "Nessuna risposta netta: gli studi erano troppo diversi per una conclusione definitiva."], "pazienti": ["🦴 Non sempre aggiungere un gesto in più durante l'operazione porta un vantaggio in più per il paziente.", "Una revisione ha guardato se trattare anche cartilagine o menisco, durante la correzione del ginocchio, aiuti davvero.", "La scelta resta del chirurgo, valutata caso per caso."]}, "reel": {"chir": ["[17 studi · 1271 ginocchia] HTO con o senza trattamento artroscopico associato.", "[Cartilagine migliora · clinica no] Nessun gesto dimostra un beneficio costante sui punteggi funzionali.", "[Troppa eterogeneità] Sintesi descrittiva, non una metanalisi vera."], "misto": ["[Un gesto in più serve?] Artroscopia associata all'osteotomia del ginocchio, sotto esame.", "[Cartilagine sì, clinica forse] Il quadro non è netto in nessuna direzione.", "[Nessuna conclusione definitiva] Gli studi erano troppo diversi fra loro."], "pazienti": ["[Un gesto in più non sempre aiuta] Un'operazione più completa non è sempre un'operazione migliore.", "[Decisione del chirurgo] La scelta resta valutata caso per caso.", "[Nessun allarme] La correzione dell'asse resta comunque un intervento valido."]}}, "7": {"video": {"chir": ["In centotrenta pazienti operati di sutura meniscale, uno studio dell'Hospital for Special Surgery confronta chi ha meno di quarant'anni con chi ne ha di più.", "A due anni, nessuna differenza significativa fra i due gruppi su punteggio IKDC, rientro allo sport o tasso di fallimento della sutura, sia nella riparazione isolata sia in quella associata alla ricostruzione del LCA — oltre l'ottanta per cento raggiunge la soglia minima di miglioramento clinicamente importante in entrambi i gruppi.", "Il gruppo over quaranta conta solo trentanove pazienti, diviso in sottogruppi ancora più piccoli: un'assenza di differenza su numeri così ridotti non è ancora una prova di equivalenza."], "misto": ["Uno studio su centotrenta pazienti operati di sutura del menisco confronta chi ha meno o più di quarant'anni.", "A due anni dall'intervento, i risultati sono sovrapponibili fra i due gruppi: stesso rientro allo sport, stesso tasso di reinfortunio, stessa soddisfazione riferita dai pazienti.", "È un segnale incoraggiante per chi ha più di quarant'anni, ma il gruppo più adulto era piccolo: serve prudenza prima di generalizzarlo a ogni caso."], "pazienti": ["Riparare il menisco invece di asportarlo può funzionare bene anche dopo i quarant'anni, secondo un nuovo studio.", "Su centotrenta pazienti operati, chi aveva più di quarant'anni è tornato allo sport e si è ripreso con risultati molto simili a chi ne aveva di meno.", "Non significa che la riparazione sia sempre possibile: resta una decisione del chirurgo basata sul tipo di lesione, non solo sull'età."]}, "linkedin": {"chir": ["Coorte retrospettiva comparativa, Hospital for Special Surgery: 130 meniscal repairs, confronto <40 vs ≥40 anni, follow-up minimo 2 anni.", "Nessuna differenza significativa su IKDC (p=,58/,72), RTS (p=,80/,24) o fallimento della sutura (p>,99/,54) fra i gruppi di età, sia isolata sia con ACLR concomitante. >80% raggiunge la MCID in entrambi i gruppi.", "Sottogruppo ≥40 anni: solo 39 pazienti, ulteriormente frazionato. Un «nessuna differenza» su numeri così piccoli non è ancora equivalenza dimostrata — conteggi grezzi non riportati per calcolare la potenza."], "misto": ["Uno studio su 130 pazienti operati di sutura meniscale confronta chi ha meno o più di 40 anni.", "A 2 anni, esiti clinici, rientro allo sport e reinfortunio sono sovrapponibili fra i due gruppi, sia nella riparazione isolata sia associata al LCA.", "Il gruppo over 40 era piccolo (39 pazienti): un segnale incoraggiante, non ancora una certezza per ogni caso."], "pazienti": ["Anche dopo i 40 anni, riparare il menisco può funzionare come nei pazienti più giovani, mostra uno studio su 130 casi.", "Rientro allo sport, reinfortunio e soddisfazione riferita dai pazienti sono simili fra chi ha meno o più di 40 anni.", "Non significa che la riparazione sia sempre l'opzione giusta: resta una scelta del chirurgo basata sul tipo di lesione."]}, "instagram": {"chir": ["📊 130 pazienti, sutura meniscale: over 40 e under 40 a confronto, follow-up 2 anni.", "Nessuna differenza su IKDC, rientro allo sport, fallimento della sutura — sia isolata sia con LCA. >80% raggiunge la MCID in entrambi i gruppi.", "Sottogruppo over 40 piccolo (39 pz): un segnale incoraggiante, non ancora una dimostrazione di equivalenza."], "misto": ["🦵 L'età, da sola, non sembra un ostacolo alla riparazione del menisco.", "Uno studio su 130 pazienti trova risultati sovrapponibili a 2 anni fra chi ha meno o più di 40 anni.", "Il gruppo più adulto era piccolo: un segnale incoraggiante, non ancora una certezza."], "pazienti": ["🩹 Anche dopo i 40 anni, riparare il menisco può funzionare come nei pazienti più giovani.", "Uno studio su 130 casi mostra risultati simili nel rientro allo sport e nel recupero, indipendentemente dall'età.", "La scelta fra riparare e asportare resta del chirurgo, basata sul tipo di lesione."]}, "reel": {"chir": ["[130 pz · sutura meniscale] Over 40 vs under 40, follow-up 2 anni.", "[Nessuna differenza] IKDC, RTS, fallimento sovrapponibili fra i gruppi.", "[Sottogruppo piccolo] 39 pazienti over 40: segnale, non prova di equivalenza."], "misto": ["[L'età non è un ostacolo] Sutura meniscale: risultati simili a ogni età, in questo studio.", "[130 pazienti] Rientro allo sport e reinfortunio sovrapponibili fra i gruppi.", "[Prudenza] Il gruppo più adulto era piccolo."], "pazienti": ["[Anche dopo i 40] Riparare il menisco può funzionare bene comunque.", "[130 pazienti] Risultati simili nel recupero, a ogni età.", "[La scelta resta del chirurgo] Dipende dal tipo di lesione, non solo dall'età."]}}, "8": {"video": {"chir": ["Una metanalisi di trentuno studi osservazionali guarda a un fattore di rischio poco discusso per l'infezione dopo protesi articolare: una precedente artroscopia sulla stessa articolazione.", "Il rischio di infezione complessiva sale con un odds ratio di uno virgola trentatré, quello di infezione profonda a uno virgola trentotto, ma solo per ginocchio e spalla — per l'anca, l'artroscopia pregressa non risulta un fattore di rischio.", "Sono tutti studi osservazionali: il confondimento per indicazione resta possibile, perché chi ha già avuto un'artroscopia può avere, in partenza, un'articolazione più compromessa."], "misto": ["Una metanalisi di trentuno studi guarda se un'artroscopia fatta anni prima pesi sul rischio di infezione quando, più avanti, si viene operati di protesi.", "Per il ginocchio e per la spalla il rischio di infezione risulta più alto in chi ha già avuto un'artroscopia; per l'anca questo legame non si vede.", "È un'associazione statistica, non una prova diretta di causa: chi ha bisogno di più interventi nel tempo può partire da un'articolazione già più compromessa."], "pazienti": ["Se hai già avuto un intervento artroscopico al ginocchio, il chirurgo potrebbe tenerne conto quando pianifica una futura protesi.", "Uno studio che ha messo insieme i dati di trentuno ricerche mostra un rischio di infezione leggermente più alto, dopo la protesi, in chi ha già subito un'artroscopia sullo stesso ginocchio.", "Non è un motivo di preoccupazione: è un'informazione che aiuta a valutare con più attenzione la prevenzione dell'infezione in questi casi specifici."]}, "linkedin": {"chir": ["Metanalisi di 31 studi osservazionali (modello lineare generalizzato misto) sull'effetto di una pregressa artroscopia sul rischio di infezione dopo artroplastica di ginocchio, anca e spalla.", "Pregressa artroscopia associata a maggiore rischio di infezione complessiva (OR 1,33; IC 95% 1,14-1,56) e profonda (OR 1,38; IC 95% 1,17-1,63), significativo per ginocchio e spalla, non per l'anca. Tasso di infezione aggregato 2%.", "Evidenza osservazionale: confondimento per indicazione plausibile. Rilevante per il colloquio preoperatorio prima di una protesi di ginocchio in pazienti con artroscopie pregresse sullo stesso ginocchio."], "misto": ["Una metanalisi di 31 studi mostra che un'artroscopia fatta in passato può pesare sul rischio di infezione dopo una futura protesi.", "Per il ginocchio e la spalla il rischio è più alto in chi ha già avuto un'artroscopia; per l'anca non si vede lo stesso legame.", "È un'associazione statistica: chi ha avuto più interventi nel tempo può partire da un'articolazione già più compromessa."], "pazienti": ["Un'artroscopia fatta anni prima al ginocchio può contare nella valutazione del rischio quando, più avanti, si fa la protesi.", "Una metanalisi di 31 studi trova un rischio di infezione leggermente più alto in questi casi.", "Non è un allarme: è un'informazione che aiuta il chirurgo a essere ancora più attento alla prevenzione."]}, "instagram": {"chir": ["🦠 31 studi: una pregressa artroscopia aumenta il rischio di infezione dopo la protesi di ginocchio.", "OR 1,33 per l'infezione complessiva, 1,38 per quella profonda — significativo per ginocchio e spalla, non per l'anca.", "Studi osservazionali: il confondimento per indicazione resta possibile."], "misto": ["🔍 Un'artroscopia fatta anni prima può pesare sul rischio della protesi di ginocchio.", "Una metanalisi di 31 studi trova un rischio più alto di infezione in chi ha già avuto un'artroscopia sullo stesso ginocchio.", "Un'associazione, non una prova diretta di causa."], "pazienti": ["🩺 Se hai già fatto un'artroscopia al ginocchio, il chirurgo ne terrà conto in vista di una futura protesi.", "Uno studio che riunisce 31 ricerche trova un rischio di infezione un po' più alto in questi casi.", "Nessun allarme: solo più attenzione nella prevenzione."]}, "reel": {"chir": ["[31 studi osservazionali] Artroscopia pregressa e rischio di infezione dopo protesi.", "[OR 1,33-1,38] Significativo per ginocchio e spalla, non per l'anca.", "[Confondimento possibile] Studi osservazionali, non causalità dimostrata."], "misto": ["[Un intervento passato conta] Artroscopia pregressa e rischio infettivo della protesi.", "[Ginocchio e spalla sì, anca no] Un pattern diverso a seconda dell'articolazione.", "[Associazione, non causa] Serve prudenza nell'interpretazione."], "pazienti": ["[Il chirurgo ne tiene conto] Un'artroscopia passata può contare per una futura protesi.", "[Rischio leggermente più alto] Da 31 studi messi insieme.", "[Nessun allarme] Solo più attenzione nella prevenzione dell'infezione."]}}};
var TAGS={"1": {"linkedin": "#RoboticArthroplasty #TotalKneeArthroplasty #OrthopaedicSurgery", "instagram": "#ProtesiGinocchio #ChirurgiaRobotica #VELYS #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #Innovazione #SaluteArticolare", "kw": "robot protesi ginocchio TC confronto, chirurgia robotica ginocchio precisione"}, "2": {"linkedin": "#ACLReconstruction #QuadricepsTendon #SportsMedicine", "instagram": "#LCA #RicostruzioneLCA #TendineQuadricipitale #Ginocchio #ChirurgiaOrtopedica #Ortopedia #MedicinaSportiva #Ricerca #Pittsburgh", "kw": "innesto tendine quadricipitale LCA, ricostruzione legamento crociato tendenze"}, "3": {"linkedin": "#VELYS #RoboticSurgery #TotalKneeArthroplasty", "instagram": "#VELYS #ProtesiGinocchio #ChirurgiaRobotica #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #Innovazione #SaluteArticolare", "kw": "VELYS protesi robotica errori tecnici, chirurgia robotica ginocchio landmarking"}, "4": {"linkedin": "#RoboticTKA #PatellarTracking #Orthopaedics", "instagram": "#ProtesiGinocchio #ChirurgiaRobotica #Rotula #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #SaluteArticolare #Innovazione", "kw": "protesi ginocchio rotula tracking, chirurgia robotica allineamento ginocchio"}, "5": {"linkedin": "#HighTibialOsteotomy #KneeAlignment #Orthopaedics", "instagram": "#Osteotomia #GinocchioVaro #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #SaluteArticolare #CorrezioneAsse #Ginocchio", "kw": "osteotomia ginocchio pianificazione radiografia, correzione asse ginocchio JLCA"}, "6": {"linkedin": "#HighTibialOsteotomy #Arthroscopy #EvidenceBasedMedicine", "instagram": "#Osteotomia #Artroscopia #Menisco #Cartilagine #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #Ginocchio", "kw": "osteotomia ginocchio artroscopia associata, correzione asse ginocchio menisco"}, "7": {"linkedin": "#MeniscusRepair #SportsMedicine #Orthopaedics", "instagram": "#Menisco #SuturaMeniscale #Ginocchio #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #RitornoAlloSport #SaluteArticolare", "kw": "sutura menisco età, riparazione menisco over 40 anni"}, "8": {"linkedin": "#PeriprostheticInfection #TotalKneeArthroplasty #Orthopaedics", "instagram": "#ProtesiGinocchio #InfezioneProtesi #Artroscopia #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #SaluteArticolare #PrevenzioneInfezioni", "kw": "artroscopia rischio infezione protesi ginocchio, protesi ginocchio infezione fattori di rischio"}};
var NLB={"1": {"prof": ["Nella protesi robotica, il sistema con TC preoperatoria batte quello senza immagini, non su tutto", "Uno studio retrospettivo con abbinamento per propensione confronta 181 protesi con un sistema robotico basato su tomografia computerizzata e 113 con un sistema senza immagini: il primo ottiene un allineamento più vicino al target pianificato e un punteggio funzionale (KSS-Funzione) migliore a 1 e 2 anni.", "La differenza sull'Oxford Knee Score, pur statisticamente significativa, non supera la soglia minima clinicamente rilevante: gli autori stessi la giudicano probabilmente non percepibile dal paziente."], "mix": ["Due modi diversi di far vedere l'osso al robot chirurgico, a confronto", "Un lavoro ha confrontato due strategie di protesi robotica di ginocchio: una che usa una TC prima dell'intervento per pianificare, una che non la usa. Nel confronto, la prima ha ottenuto un posizionamento più preciso dell'impianto e un punteggio funzionale migliore dopo uno e due anni.", "Non tutte le differenze misurate sono abbastanza grandi da essere percepite dal paziente: una di queste, pur statisticamente significativa, resta sotto la soglia che gli stessi ricercatori considerano clinicamente rilevante."], "paz": ["Anche fra i robot chirurgici per la protesi di ginocchio ci sono differenze", "Un confronto fra due modi diversi in cui un sistema robotico pianifica l'intervento di protesi — uno con una TC preoperatoria, uno senza — ha trovato un miglior posizionamento dell'impianto e una ripresa funzionale leggermente migliore col primo metodo.", "Non significa che un metodo sia sbagliato: entrambi restano interventi validi, e la differenza osservata in uno dei punteggi era talmente piccola che gli stessi ricercatori la considerano poco percepibile per chi la vive."], "kw": "robot ginocchio TC confronto, protesi ginocchio robotica precisione"}, "2": {"prof": ["A Pittsburgh il tendine quadricipitale cresce, l'hamstring cala: 26 anni di dati", "Analisi retrospettiva di 7657 ricostruzioni del LCA in un unico grande centro accademico americano dal 2000 al 2025: l'uso del tendine quadricipitale come innesto primario aumenta in modo significativo dal 2016, mentre l'hamstring cala in media dell'8,3% l'anno per tutto il periodo.", "È la tendenza di un solo centro, per quanto ampio: riflette anche la scuola e le preferenze locali, non un consenso internazionale, e l'analisi non riporta alcuna informazione sull'uso di un rinforzo extra-articolare laterale accanto ai vari innesti."], "mix": ["Come sceglie l'innesto per il crociato un grande centro americano, in 26 anni", "Un'analisi su quasi 8000 ricostruzioni del legamento crociato anteriore eseguite nello stesso ospedale dal 2000 al 2025 mostra un cambiamento netto: il tendine quadricipitale, poco usato all'inizio, è salito con continuità dal 2016, mentre l'uso del tendine hamstring si è ridotto in modo costante.", "Racconta come è cambiata la pratica di un centro nel tempo, non dimostra che un innesto sia clinicamente superiore a un altro: la scelta dipende anche da fattori del paziente e dall'esperienza del chirurgo."], "paz": ["Negli Stati Uniti cresce l'uso del tendine del quadricipite per il crociato", "Un grande ospedale americano ha analizzato tutte le sue ricostruzioni del legamento crociato anteriore degli ultimi 26 anni: l'innesto prelevato dal tendine del muscolo quadricipite, poco usato all'inizio, oggi viene scelto sempre più spesso, mentre l'uso di un altro tendine (hamstring, dietro il ginocchio) si è ridotto.", "Non vuol dire che un innesto sia sempre meglio di un altro: la scelta resta individuale, e dipende da tanti fattori valutati caso per caso dal chirurgo."], "kw": "innesto tendine quadricipitale LCA, ricostruzione crociato tendenze"}, "3": {"prof": ["Una guida tecnica per evitare gli errori di puntamento con VELYS", "Otto chirurghi europei descrivono gli errori più frequenti nell'acquisizione dei riferimenti anatomici con il sistema robotico senza immagini VELYS, e i segnali intraoperatori per riconoscerli prima della resezione ossea.", "È una guida di opinione basata sull'esperienza clinica, senza numeri su quanto questi errori siano frequenti né un confronto con altri sistemi robotici."], "mix": ["Come non sbagliare i punti di riferimento con un robot chirurgico per protesi", "Alcuni chirurghi esperti hanno raccolto in una guida gli errori più comuni che si possono fare all'inizio, quando si impara a usare un sistema robotico senza immagini per la protesi di ginocchio, e come accorgersene prima che l'errore diventi un taglio osseo sbagliato.", "È un testo di esperienza pratica, non uno studio con numeri e statistiche: non dice quanto siano frequenti questi errori nella realtà."], "paz": ["Anche i robot chirurgici hanno bisogno di essere guidati bene dal chirurgo", "Un gruppo di chirurghi ha scritto una guida su come evitare piccoli errori tecnici quando si comincia a usare un particolare sistema robotico per la protesi di ginocchio, per assicurarsi che il robot lavori sui riferimenti giusti.", "È un promemoria tecnico per i chirurghi, non uno studio con pazienti: non misura quanto questi accorgimenti cambino davvero il risultato dell'intervento."], "kw": "VELYS protesi robotica errori, chirurgia robotica ginocchio precisione"}, "4": {"prof": ["Il sovradimensionamento del condilo laterale peggiora il tracking rotuleo", "Analisi retrospettiva di 241 protesi robot-assistite con conservazione del crociato: un condilo femorale laterale lasciato più spesso del previsto si associa a un peggior scorrimento della rotula durante l'intervento e a una maggiore inclinazione laterale della rotula dopo l'intervento.", "L'abstract non riporta i valori numerici precisi delle associazioni, solo la loro direzione e significatività statistica; i dati vengono da un solo sistema robotico, diverso da VELYS."], "mix": ["Come l'allineamento del ginocchio durante la protesi influenza la rotula", "Uno studio ha analizzato i dati registrati dal robot chirurgico in 241 interventi di protesi di ginocchio, trovando che lasciare troppo spessore osseo su un lato del femore cambia il modo in cui la rotula scorre durante e dopo l'intervento.", "È un'osservazione su dati già raccolti per pianificare l'intervento, non uno studio randomizzato: mostra un'associazione, non dimostra in modo definitivo la causa."], "paz": ["Anche piccoli dettagli tecnici della protesi possono influenzare il movimento della rotula", "Un'analisi dei dati di un sistema robotico ha mostrato che il modo in cui viene tagliato l'osso da un lato del ginocchio può cambiare come si muove la rotula dopo la protesi.", "È un'informazione tecnica per i chirurghi, utile per affinare la pianificazione dell'intervento; non cambia le indicazioni generali all'intervento di protesi."], "kw": "protesi ginocchio rotula allineamento, tracking rotuleo protesi robotica"}, "5": {"prof": ["Prima dell'osteotomia, conta anche la differenza fra radiografia in piedi e sdraiati", "In 40 osteotomie tibiali alte a cuneo di chiusura, la differenza preoperatoria fra l'angolo articolare misurato in piedi e da sdraiati predice la direzione dello scostamento della correzione ottenuta rispetto a quella pianificata.", "Studio retrospettivo su soli 40 pazienti, un solo centro, riguarda la tecnica a cuneo di chiusura: non è detto che lo stesso schema valga per l'osteotomia ad apertura mediale."], "mix": ["Un dettaglio della radiografia che può cambiare il risultato dell'osteotomia", "Un lavoro giapponese mostra che, prima di un'osteotomia correttiva del ginocchio, la differenza fra come appare l'articolazione in piedi e da sdraiati aiuta a prevedere se la correzione finale sarà minore o maggiore di quella programmata.", "È uno studio piccolo, su una sola tecnica di osteotomia e un solo centro: un segnale utile per la pianificazione, non una regola valida per ogni caso."], "paz": ["Anche la posizione durante la radiografia conta, prima di un'osteotomia del ginocchio", "Uno studio ha mostrato che, quando si programma un intervento di correzione dell'asse del ginocchio, la differenza fra la radiografia fatta in piedi e quella fatta da sdraiati può aiutare il chirurgo a prevedere meglio il risultato della correzione.", "È un dettaglio tecnico che riguarda la pianificazione dell'intervento da parte del chirurgo, non richiede niente di diverso da parte del paziente."], "kw": "osteotomia ginocchio pianificazione, correzione asse ginocchio radiografia"}, "6": {"prof": ["Aggiungere l'artroscopia all'osteotomia non porta un beneficio clinico costante", "Revisione sistematica di 17 studi comparativi su 1271 ginocchia: trattare cartilagine o menisco per via artroscopica insieme all'osteotomia valgizzante migliora l'aspetto della cartilagine alla seconda artroscopia, ma nessun gesto aggiuntivo dimostra in modo costante un beneficio clinico superiore alla sola osteotomia.", "L'eterogeneità degli studi inclusi ha impedito una metanalisi vera e propria: la sintesi è descrittiva, senza un effetto aggregato quantificato."], "mix": ["Serve davvero fare l'artroscopia insieme all'osteotomia del ginocchio?", "Una revisione di 17 studi ha confrontato l'osteotomia correttiva del ginocchio da sola con la stessa osteotomia accompagnata da un trattamento artroscopico di cartilagine o menisco: l'aspetto della cartilagine può migliorare, ma i punteggi clinici dei pazienti non migliorano in modo costante.", "Gli studi inclusi erano troppo diversi fra loro per essere sommati in un unico calcolo statistico: la conclusione è una tendenza descrittiva, non un numero definitivo."], "paz": ["Non sempre aggiungere un gesto in più all'operazione porta un vantaggio in più", "Una revisione della letteratura ha guardato se, durante l'operazione di correzione dell'asse del ginocchio, aggiungere un trattamento artroscopico su cartilagine o menisco porti un beneficio in più rispetto alla sola correzione.", "Il risultato non è a favore né contro in modo netto: la scelta di aggiungere o meno questo gesto resta una valutazione del chirurgo caso per caso, non una regola generale."], "kw": "osteotomia ginocchio artroscopia, correzione asse ginocchio menisco cartilagine"}, "7": {"prof": ["Dopo i 40 anni, la sutura meniscale funziona come nei pazienti più giovani", "In 130 pazienti operati di sutura meniscale, i pazienti di 40 anni o più hanno esiti riferiti, rientro allo sport e tassi di fallimento a 2 anni sovrapponibili a quelli under 40, sia nella sutura isolata sia in quella associata alla ricostruzione del LCA.", "Il sottogruppo di 40 anni o più conta solo 39 pazienti, ulteriormente diviso in sottogruppi più piccoli: un'assenza di differenza su numeri così ridotti non equivale a una dimostrazione di equivalenza."], "mix": ["L'età, da sola, non sembra un ostacolo alla riparazione del menisco", "Uno studio retrospettivo su 130 pazienti operati di sutura meniscale non trova differenze significative, a 2 anni, fra chi ha più o meno di 40 anni: stessi tassi di rientro allo sport, di reinfortunio e di soddisfazione riferita dal paziente.", "È un segnale incoraggiante per chi ha più di 40 anni e una lesione riparabile, ma il gruppo più adulto era piccolo: serve prudenza prima di generalizzarlo a ogni caso."], "paz": ["Anche dopo i 40 anni, riparare il menisco può funzionare come nei più giovani", "Uno studio su 130 pazienti operati di sutura del menisco ha trovato che chi ha più di 40 anni recupera e torna allo sport con risultati simili a chi ne ha meno, quando il menisco viene riparato invece che asportato.", "Non significa che la riparazione sia sempre possibile: resta una decisione del chirurgo basata sul tipo di lesione, non solo sull'età del paziente."], "kw": "sutura menisco età, riparazione menisco over 40"}, "8": {"prof": ["Un'artroscopia pregressa aumenta il rischio di infezione dopo la protesi di ginocchio", "Metanalisi di 31 studi osservazionali: una precedente artroscopia del ginocchio è associata a un rischio più alto di infezione dopo la protesi (odds ratio 1,33 complessivo, 1,38 per l'infezione profonda), con un pattern diverso da quello dell'anca, dove l'artroscopia pregressa non risulta un fattore di rischio.", "Studi osservazionali: il confondimento per indicazione resta possibile, perché chi ha già avuto un'artroscopia può avere un ginocchio già più compromesso in partenza."], "mix": ["Un'artroscopia fatta anni prima può pesare sul rischio della protesi", "Una metanalisi di 31 studi mostra che chi ha già subito un'artroscopia di ginocchio ha un rischio più alto di infezione quando viene poi operato di protesi, mentre per l'anca questo legame non si vede.", "È un'associazione statistica, non una prova diretta di causa: chi ha bisogno di più interventi nel tempo può avere, in partenza, un ginocchio più compromesso rispetto a chi non ne ha mai avuto bisogno."], "paz": ["Se hai già fatto un'artroscopia al ginocchio, il chirurgo ne terrà conto per la protesi", "Uno studio che ha messo insieme i dati di 31 ricerche mostra che chi ha già avuto un intervento artroscopico al ginocchio ha un rischio leggermente più alto di infezione quando, più avanti, viene operato di protesi.", "Non è un motivo per preoccuparsi: è un'informazione che aiuta il chirurgo a valutare con più attenzione la prevenzione dell'infezione in questi casi."], "kw": "artroscopia rischio infezione protesi, protesi ginocchio infezione fattori rischio"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"The Journal of Knee Surgery",h:"Robot con TC preoperatoria più preciso di uno senza immagini",v:"Uno studio retrospettivo con abbinamento per punteggio di propensione confronta un sistema robotico basato su TC con uno senza immagini nella protesi totale di ginocchio: il primo ottiene un allineamento più vicino al target pianificato e punteggi funzionali migliori a 1-2 anni, anche se una delle differenze non supera la soglia clinicamente rilevante.",ax:"Cheong, Chen et al.",date:"set 2026",meta:"coorte retrospettiva con abbinamento per propensione, 181 TC-based/113 CT-free · [III]",pmid:'42674008',doi:'10.1055/a-2939-2755',journal:"The Journal of Knee Surgery",authors:"Cheong ZJ, Chen AKY, Cheng Z, Lim DMW, Leng TT, Thwin L",design:"Studio monocentrico retrospettivo con abbinamento per punteggio di propensione, confronto fra un sistema robotico per protesi totale di ginocchio basato su tomografia computerizzata (TC), semi-attivo, e un sistema senza immagini preoperatorie (CT-free), passivo; esiti funzionali e posizionamento dell'impianto valutati nel pre-operatorio e a 3 mesi, 1 e 2 anni.",pop:"294 pazienti dopo abbinamento per propensione: 181 nel gruppo TC-based, 113 nel gruppo CT-free.",results:"A 1 anno il gruppo TC-based ha un punteggio KSS-Funzione migliore (78,2 contro 65,9); a 2 anni resta migliore (78 contro 72) e supera la differenza minima clinicamente importante (MCID) pubblicata. L'Oxford Knee Score a 2 anni è migliore nel gruppo TC-based (41,7 contro 39,8), ma questa differenza non supera la MCID pubblicata: gli stessi autori la considerano verosimilmente non rilevante sul piano clinico nonostante la significatività statistica. Nessuna differenza significativa su dolore VAS o range di movimento passivo. L'allineamento è più vicino al target pianificato nel gruppo TC-based: angolo tibiale prossimale mediale 90,0° contro 87,8°, angolo anca-ginocchio-caviglia -0,22° contro -2,52°, flessione femorale 3,22°±0,37° contro 0,15°±0,47° (p=0,001, target 3°); nessuna differenza sullo slope tibiale posteriore.",concl:"Gli autori concludono che il sistema robotico basato su TC, semi-attivo, ottiene esiti funzionali migliori e un posizionamento dell'impianto più accurato rispetto al sistema senza immagini, passivo.",limits:"Studio retrospettivo monocentrico, non randomizzato: l'abbinamento per propensione riduce ma non elimina la possibile selezione dei pazienti · l'abstract non nomina le piattaforme commerciali confrontate · la differenza sull'Oxford Knee Score a 2 anni, pur statisticamente significativa, non supera la MCID pubblicata — un esito clinicamente incerto nonostante il valore p.",perte:"Il tuo VELYS è un sistema senza immagini preoperatorie (image-free): questo lavoro colloca la categoria a cui appartiene un gradino sotto un sistema TC-based su alcuni esiti, anche se non lo nomina direttamente e la differenza funzionale più solida (KSS-F) convive con una differenza (OKS) che gli stessi autori giudicano probabilmente non rilevante. Non è una dimostrazione che VELYS specificamente sia inferiore — lo studio non lo include — ma è il primo confronto diretto fra le due filosofie di navigazione che vale la pena conoscere."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Journal of ISAKOS",h:"Il tendine quadricipitale cresce, l'hamstring cala: 26 anni a Pittsburgh",v:"Analisi di 26 anni (2000-2025) su 7657 ricostruzioni del LCA in un unico grande centro USA: l'uso del tendine quadricipitale come innesto primario è salito in modo significativo dal 2016, mentre l'hamstring è sceso in media dell'8,3% l'anno per tutto il periodo.",ax:"Giusto, Dadoo et al., con Volker Musahl",date:"set 2026",meta:"coorte retrospettiva monocentrica, 7657 ricostruzioni/26 anni · [III]",pmid:'42710782',doi:'10.1016/j.jisako.2026.101214',journal:"Journal of ISAKOS",authors:"Giusto JD, Dadoo S, Bhardwaj N, Sebastiani R, Hartline J, Poploski KM, Irrgang JJ, Lesniak BP, Hughes JD, Musahl V",design:"Studio retrospettivo di coorte su tutti i pazienti sottoposti a ricostruzione primaria o di revisione del legamento crociato anteriore (LCA) da 10 chirurghi dello stesso grande centro accademico statunitense (UPMC Freddie Fu Sports Medicine Center, Pittsburgh) fra il 2000 e il 2025, esclusa la chirurgia multilegamentosa e l'età <14 anni; regressione multinomiale per le tendenze nella scelta dell'innesto rispetto all'osso-tendine-osso (BPTB) come riferimento, analisi di Joinpoint per identificare i periodi di cambiamento significativo.",pop:"7657 pazienti su 8288 identificati inizialmente (esclusi per i criteri sopra), età media 26±11 anni, 44% donne. Ricostruzione primaria 86% (6585), di revisione 14% (1072).",results:"L'allograft rappresenta il 34% di tutte le ricostruzioni (2577), con un picco nel 2007 durante l'epoca della tecnica a doppio fascio. Fra gli autoinnesti: osso-tendine-osso (BPTB) 24% (1807), hamstring 23% (1729), tendine quadricipitale (QT) 20% (1544). Il QT autoinnesto primario aumenta in modo significativo rispetto al BPTB (odds ratio 1,19; p<0,01); l'hamstring primario diminuisce in modo significativo (odds ratio 0,89; p<0,01). L'analisi di Joinpoint mostra un aumento del QT primario fra il 2016 e il 2019 (p=0,03) e del QT di revisione fra il 2012 e il 2019 (p<0,01), mentre l'hamstring primario cala in media dell'8,3% l'anno per tutto il periodo 2000-2025 (p<0,01). Nella revisione, il QT aumenta (odds ratio 1,15; p<0,01) e l'allograft diminuisce (odds ratio 0,88; p<0,01), con un calo di Joinpoint dell'8,1% l'anno per l'allograft di revisione (p<0,01).",concl:"Gli autori concludono che, nello stesso grande centro, l'uso del tendine quadricipitale è aumentato in modo significativo sia in prima ricostruzione (2016-2019) sia in revisione (2012-2019), mentre l'hamstring in prima ricostruzione e l'allograft in revisione sono calati in modo costante lungo tutto il periodo studiato.",limits:"Dati di un solo centro, per quanto grande e con 10 chirurghi diversi: la tendenza riflette anche le preferenze locali, non necessariamente un consenso nazionale o internazionale · studio retrospettivo di registro istituzionale, livello III · l'abstract non riporta se e come sia cambiato, nello stesso periodo, l'uso di un rinforzo extra-articolare laterale accanto ai vari innesti — non dice nulla sulla combinazione innesto+LET che tu esegui sempre.",perte:"Pittsburgh e il gruppo di Volker Musahl sono la scuola di riferimento che segui per il tendine quadricipitale (04-fonti.md): vedere che nel loro stesso centro il QT sale con continuità dal 2016 mentre l'hamstring scende dell'8,3% l'anno conferma che il campo si sta muovendo verso l'innesto che hai già scelto. Non è una dimostrazione di superiorità clinica — è epidemiologia descrittiva di preferenza chirurgica in un centro — e non tocca in alcun modo la questione del LET che resta al centro di T1a."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Una guida tecnica per evitare gli errori di puntamento con VELYS",v:"Guida tecnica di otto chirurghi europei sugli errori più comuni nel posizionamento dei riferimenti anatomici (landmarking) con il sistema robotico senza immagini VELYS, e su come riconoscerli in sala prima di eseguire le resezioni ossee.",ax:"Aichmair, Graichen et al.",date:"set 2026",meta:"guida tecnica basata sull'esperienza clinica degli autori · [V]",pmid:'42708076',doi:'10.1002/jeo2.70902',journal:"Journal of Experimental Orthopaedics",authors:"Aichmair A, Graichen H, Snir N, Bloch BV, Ihekweazu UN, Hofstaetter JG, Hirschmann MT, Vandekerckhove PJ",design:"Guida tecnica basata sull'esperienza clinica degli autori (otto chirurghi di sei paesi europei/Israele), non uno studio su una casistica propria: descrive i punti critici dell'acquisizione dei riferimenti anatomici (landmarking) e della valutazione del bilanciamento degli spazi articolari nella protesi totale di ginocchio robot-assistita con il sistema senza immagini VELYS, con l'obiettivo di aiutare i chirurghi che iniziano a usarlo a riconoscere gli errori prima della resezione ossea.",pop:"Non applicabile: guida tecnica, non uno studio su una coorte di pazienti.",results:"Non riportati numeri: gli autori descrivono qualitativamente gli errori più frequenti — posizionamento dei pin, controllo dei punti di repere ossei, acquisizione dei riferimenti anatomici — e i segnali intraoperatori che permettono di riconoscerli prima di eseguire le resezioni, senza quantificarne la frequenza né confrontarli con altri sistemi.",concl:"Gli autori concludono che questa guida può aiutare chi inizia a usare VELYS a prevenire imprecisioni di posizionamento, evidenziando i punti critici dell'acquisizione dei riferimenti prima che diventino errori di resezione.",limits:"Livello V: opinione di esperti basata sull'esperienza clinica, non uno studio con una casistica propria · nessun dato quantitativo su frequenza o gravità degli errori descritti · non confronta VELYS con altri sistemi robotici, né stima quanto queste raccomandazioni riducano davvero gli errori nella pratica.",perte:"Materiale operativo diretto per la piattaforma che usi: un promemoria dei punti in cui il posizionamento dei pin e l'acquisizione dei riferimenti possono introdurre un errore silenzioso prima che la resezione lo renda irreversibile — vale la pena leggerlo per intero, anche senza numeri da citare."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Robotic Surgery",h:"Il sovradimensionamento del condilo laterale peggiora il tracking rotuleo",v:"In 241 protesi robot-assistite con conservazione del crociato posteriore, un condilo femorale laterale distale lasciato più spesso del previsto («overstuffing») si associa a un tracking rotuleo intraoperatorio peggiore e a una maggiore inclinazione rotulea laterale dopo l'intervento.",ax:"Xu, Zhang et al.",date:"set 2026",meta:"analisi retrospettiva di dati robotici, 241 protesi (sistema MAKO) · [III]",pmid:'42684569',doi:'10.1007/s11701-026-03915-3',journal:"Journal of Robotic Surgery",authors:"Xu N, Zhang R, Liu S, Wang Z, Xu H, Zhang H, Xiang S",design:"Analisi retrospettiva dei dati intraoperatori registrati dal sistema robotico MAKO in 241 protesi totali di ginocchio con conservazione del crociato posteriore (CR), robot-assistite; confronto fra i casi che hanno richiesto un release del retinacolo laterale (LRR) e quelli che non l'hanno richiesto, e regressione multivariata per correlare allineamento coronale, sovradimensionamento femorale distale e tracking rotuleo intra e postoperatorio.",pop:"241 protesi totali di ginocchio robot-assistite con conservazione del crociato posteriore.",results:"Il gruppo che ha richiesto il release del retinacolo laterale (LRR) ha un angolo femorale distale laterale nativo e finale più valgo e uno spessore di resezione del condilo distale laterale inferiore, con una differenza finale-nativo di quell'angolo maggiore. Un angolo nativo più valgo, una differenza finale-nativo maggiore e una resezione del condilo distale laterale più sottile aumentano tutti la probabilità di richiedere il release; una differenza finale-nativo maggiore di quell'angolo si associa anche a una maggiore inclinazione rotulea laterale postoperatoria. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract: gli autori descrivono le associazioni come statisticamente significative senza riportarne i valori numerici precisi.",concl:"Gli autori concludono che il sovradimensionamento del condilo femorale distale laterale — causato da un angolo nativo più valgo, una correzione maggiore o una resezione più sottile — aumenta il rischio di dover eseguire un release del retinacolo laterale e di un'alterazione del tracking rotuleo dopo la protesi con conservazione del crociato.",limits:"Studio retrospettivo su dati di un solo sistema robotico (MAKO), non VELYS · dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract, solo la direzione e la significatività statistica · associazioni osservazionali sugli stessi dati intraoperatori usati per pianificare l'intervento, non uno studio randomizzato.",perte:"Il principio — l'allineamento coronale e lo spessore di resezione del condilo laterale condizionano il tracking rotuleo, non solo la stabilità legamentosa — vale per qualunque piattaforma robotica di protesi con conservazione del crociato, VELYS compreso, anche se i dati numerici qui vengono da un sistema diverso dal tuo."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Prima dell'osteotomia, conta la differenza fra radiografia in piedi e sdraiati",v:"In 40 osteotomie tibiali alte a cuneo di chiusura, la differenza preoperatoria fra l'angolo di convergenza della linea articolare misurato in piedi e da sdraiati predice quanto la correzione si scosterà dal piano, in un senso o nell'altro a seconda di quale radiografia si usa per pianificare.",ax:"Kubo, Uenaka et al.",date:"set 2026",meta:"coorte retrospettiva monocentrica, 40 ginocchia · [IV]",pmid:'42708052',doi:'10.1002/jeo2.70904',journal:"Journal of Experimental Orthopaedics",authors:"Kubo M, Uenaka K, Fujikawa H, Maeda T, Kumagai K, Nosaka Y, Horikawa S, Imai S",design:"Studio retrospettivo monocentrico su pazienti con patologia del comparto mediale del ginocchio sottoposti a osteotomia tibiale alta a cuneo di chiusura (CWHTO) fra il 2009 e il 2017; l'angolo di convergenza della linea articolare (JLCA) è stato misurato su radiografie in carico, supine e sotto stress preoperatorie, e il cambiamento postoperatorio della JLCA calcolato usando come riferimento sia la radiografia supina sia quella in carico preoperatoria.",pop:"40 pazienti (29 donne, 11 uomini), età media 60,3 anni (range 39-77), radiografie postoperatorie a una media di 9,9 mesi (range 2-14).",results:"La differenza preoperatoria fra JLCA in carico e supina (dJLCA) è correlata positivamente con il cambiamento di JLCA calcolato da supina preoperatoria a carico postoperatoria (r=0,52; p=0,001) e negativamente con il cambiamento calcolato da carico preoperatoria a carico postoperatoria (r=-0,43; p=0,007). All'analisi multivariabile la dJLCA resta associata in modo indipendente a entrambi gli esiti (r=0,51; p=0,006 e r=-0,49; p=0,008).",concl:"Gli autori concludono che la differenza preoperatoria fra JLCA in carico e supina è il principale determinante del cambiamento postoperatorio della JLCA dopo CWHTO: una differenza maggiore porta a una sottocorrezione se si pianifica sulla radiografia supina, e a una sovracorrezione se si pianifica su quella in carico.",limits:"Studio retrospettivo monocentrico su soli 40 pazienti, livello IV · riguarda l'osteotomia a cuneo di chiusura, non quella ad apertura mediale più diffusa altrove · follow-up radiografico breve e variabile (2-14 mesi), non dice nulla sulla tenuta della correzione a lungo termine.",perte:"Un promemoria pratico per la pianificazione preoperatoria di qualunque osteotomia tibiale alta: la scelta della radiografia di riferimento (in carico o supina) non è neutra quando la differenza fra le due è ampia, e ignorarla può spiegare parte della variabilità della correzione ottenuta rispetto a quella pianificata."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Aggiungere l'artroscopia all'osteotomia non porta un beneficio costante",v:"Revisione sistematica di 17 studi comparativi (1271 ginocchia): trattare cartilagine o menisco per via artroscopica insieme all'osteotomia valgizzante migliora l'aspetto della cartilagine alla seconda artroscopia, ma nessun gesto aggiuntivo — microfratture, microforature, abrasione, meniscectomia o centralizzazione meniscale — dimostra in modo costante un beneficio clinico in più rispetto alla sola osteotomia.",ax:"Duru, Mussie et al.",date:"set 2026",meta:"revisione sistematica di 17 studi comparativi, 1271 ginocchia · [III]",pmid:'42708054',doi:'10.1002/jeo2.70903',journal:"Journal of Experimental Orthopaedics",authors:"Duru DO, Mussie E, Sehgol TA, Nakanishi Y, Degen RM",design:"Revisione sistematica secondo ricerca su MEDLINE, Embase e CENTRAL dall'origine al 17 maggio 2026, di studi comparativi che riportano gli esiti dell'osteotomia tibiale alta valgizzante (HTO) associata a un trattamento artroscopico di cartilagine (microfrattura, microforatura, abrasione) e/o menisco (centralizzazione, meniscectomia, riparazione) rispetto alla sola HTO. Per l'eterogeneità degli studi non è stata eseguita una metanalisi: gli esiti sono stati sintetizzati in modo descrittivo, stratificati per tipo di gesto artroscopico associato.",pop:"17 studi, 1271 ginocchia: 663 trattate con HTO più artroscopia, 608 con sola HTO. Età media 57,0 anni nel gruppo combinato e 55,1 nel gruppo HTO da sola; follow-up medio 32,9 e 31,0 mesi.",results:"Sintesi descrittiva, non metanalisi: nessun effetto aggregato calcolato per l'eterogeneità dichiarata dagli autori. Entrambi i gruppi migliorano in generale su punteggi riferiti dal paziente, esiti funzionali e allineamento radiografico, ma nessun gesto artroscopico associato mostra un beneficio clinico aggiuntivo costante: la microfrattura ha effetti incoerenti su Lysholm e WOMAC, la meniscectomia non migliora il Knee Society Score, la centralizzazione meniscale mostra risultati incoerenti su KOOS e allineamento. Microfrattura, microforatura, abrasione e centralizzazione meniscale migliorano l'aspetto della cartilagine alla seconda artroscopia (second-look), ma questo miglioramento non si traduce in modo costante in punteggi clinici superiori.",concl:"Gli autori concludono che l'evidenza attuale non dimostra un beneficio clinico costante nell'aggiungere un trattamento artroscopico di cartilagine o menisco all'osteotomia valgizzante, nonostante un miglioramento dell'aspetto cartilagineo alla seconda artroscopia in alcuni casi; servono studi comparativi dedicati a ciascun gesto specifico.",limits:"Eterogeneità tale da impedire la metanalisi: la sintesi è descrittiva, senza un effetto aggregato quantificato · qualità e disegno degli studi inclusi non uniformi (comparativi ma non necessariamente randomizzati) · la segnalazione delle complicanze è definita dagli stessi autori «liminata ed eterogenea».",perte:"Riguarda direttamente la parte della tua pratica in cui osteotomia e menisco si incontrano: la centralizzazione meniscale aggiunta all'HTO — non solo alla sutura transtibiale della radice, come già discusso in T2b — non mostra qui un beneficio clinico costante rispetto alla sola osteotomia, un secondo segnale nella stessa direzione da un angolo diverso."},{n:7,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Dopo i 40 anni la sutura meniscale funziona come nei più giovani",v:"In 130 pazienti operati di sutura meniscale, chi ha 40 anni o più torna allo sport, non si reinfortuna e riferisce esiti clinici a 2 anni sovrapponibili a chi ha meno di 40 anni, sia nella sutura isolata sia in quella associata alla ricostruzione del LCA.",ax:"White, Uppstrom et al.",date:"set 2026",meta:"coorte retrospettiva comparativa, 130 pz · [III]",pmid:'42707055',doi:'10.1002/ars2.70071',journal:"Arthroscopy, Sports Medicine, and Rehabilitation",authors:"White AE, Uppstrom TJ, Raghuram AK, Itthipanichpong T, Menta SV, Baldwin RB, Wang SH, Ranawat AS",design:"Studio retrospettivo comparativo, singolo centro terziario (Hospital for Special Surgery), su tutte le suture meniscali eseguite fra dicembre 2010 e agosto 2021 con almeno 2 anni di follow-up; confronto fra pazienti <40 e ≥40 anni, separatamente per sutura meniscale isolata e sutura associata a ricostruzione del legamento crociato anteriore (LCA).",pop:"130 pazienti: 91 <40 anni, 39 ≥40 anni (56% uomini). Lesioni: 66,2% mediali, 26,9% laterali, 6,9% entrambe.",results:"Nei pazienti con ricostruzione del LCA associata, nessuna differenza significativa fra i gruppi di età nel punteggio IKDC a 2 anni (p=,58), nel rientro allo sport (p=,80) o nel tasso di fallimento della sutura meniscale (p>,99). Nella sutura meniscale isolata, nessuna differenza significativa fra i gruppi di età su IKDC a 2 anni (p=,72), rientro allo sport (p=,24) o fallimento della sutura (p=,54). A 2 anni, oltre l'80% dei pazienti in entrambi i gruppi di età raggiunge la differenza minima clinicamente importante su tutti gli esiti riferiti dal paziente, senza differenze significative fra i gruppi.",concl:"Gli autori concludono che i pazienti di 40 anni o più sottoposti a sutura meniscale hanno esiti riferiti dal paziente, tassi di rientro allo sport e tassi di fallimento a 2 anni sovrapponibili a quelli dei pazienti più giovani.",limits:"Studio retrospettivo di livello III, singolo centro · il sottogruppo ≥40 anni (39 pazienti) si divide ulteriormente fra sutura isolata e associata al LCA, con numeri per braccio verosimilmente piccoli: l'abstract non riporta i conteggi grezzi di fallimento per calcolarne la potenza, e un «nessuna differenza» su un sottogruppo così piccolo non è ancora una dimostrazione di equivalenza.",perte:"Un argomento utile nel colloquio con i pazienti più adulti candidati a una riparazione meniscale piuttosto che a una meniscectomia: l'età sopra i 40 anni, da sola, non sembra qui un motivo per aspettarsi risultati peggiori — ma il sottogruppo che lo dimostra è piccolo."},{n:8,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Investigative Surgery",h:"Un'artroscopia pregressa aumenta il rischio di infezione dopo la protesi",v:"Metanalisi di 31 studi osservazionali: una precedente artroscopia del ginocchio è associata a un rischio più alto di infezione dopo la protesi di ginocchio, con un pattern diverso da quello dell'anca, dove l'artroscopia pregressa non risulta un fattore di rischio.",ax:"Liu, Wu et al.",date:"set 2026",meta:"metanalisi di 31 studi osservazionali · [II]",pmid:'42704073',doi:'10.1080/08941939.2026.2702155',journal:"Journal of Investigative Surgery",authors:"Liu H, Wu B, Chang Z, Wang X",design:"Metanalisi di 31 studi osservazionali (ricerca su quattro banche dati in lingua inglese fino al 10 agosto 2025) sull'effetto di una pregressa chirurgia artroscopica sul rischio di infezione dopo protesi di ginocchio, anca o spalla; modello lineare generalizzato misto per calcolare gli odds ratio aggregati, con analisi per sottogruppo per articolazione.",pop:"31 studi osservazionali inclusi nella metanalisi (numero di pazienti non riportato in forma aggregata nell'abstract).",results:"Una pregressa chirurgia artroscopica aumenta in modo significativo il rischio di infezione complessiva dopo protesi articolare (odds ratio 1,33; IC 95% 1,14-1,56) e di infezione profonda (odds ratio 1,38; IC 95% 1,17-1,63), con eterogeneità evidente fra articolazioni diverse. Una pregressa artroscopia di ginocchio è associata a un rischio più alto di infezione dopo protesi di ginocchio; una pregressa artroscopia di spalla aumenta in modo marcato il rischio di infezione profonda dopo protesi di spalla. Nessuna correlazione significativa fra artroscopia d'anca pregressa e rischio di infezione dopo protesi d'anca. Il tasso di infezione aggregato, complessivo e profondo, è del 2% in questa popolazione.",concl:"Gli autori concludono che il rischio di infezione legato a una pregressa artroscopia dipende dall'articolazione: rilevante per ginocchio e spalla, non per l'anca, e raccomandano di tenerne conto nella pianificazione del trattamento.",limits:"Metanalisi di studi osservazionali, non di trial randomizzati: il confondimento per indicazione resta possibile — chi ha già avuto un'artroscopia può avere un ginocchio più compromesso in partenza, non necessariamente un rischio infettivo intrinsecamente più alto · eterogeneità dichiarata «evidente» fra articolazioni · numero di pazienti aggregato non riportato nell'abstract.",perte:"Rilevante per il colloquio preoperatorio prima di una protesi di ginocchio in un paziente con una o più artroscopie pregresse sullo stesso ginocchio — comprese quelle che hai eseguito tu anni prima per menisco o cartilagine: il rischio di infezione, per questa metanalisi, non è uguale a chi non ha mai avuto un'artroscopia sullo stesso ginocchio."}];
var SUGGQ=[{"k": "kol", "n": "Ryan M. Degen", "w": "Western University, Fowler Kennedy Sport Medicine Clinic, Londra (Ontario, Canada)", "r": "Autore senior della revisione sistematica di oggi su osteotomia tibiale alta e trattamento artroscopico associato, e coautore — con lo stesso primo autore, Duru — della scoping review dell'8 settembre sulla revisione del LCA fallito dopo LET: corrispondenza tecnica diretta con la tua doppia pratica di osteotomie correttive e ricostruzioni legamentose associate. Sostituisce la proposta invariata di Adam B. Yanke (8 settembre)."}];
var BRIEF_TEXT="Otto lavori oggi, nessuno rosso, uno arancione. Il lavoro arancione mette a confronto due modi di guidare il robot chirurgico nella protesi di ginocchio: uno che si basa su una tomografia computerizzata fatta prima dell'intervento, l'altro senza immagini preoperatorie. Nel confronto retrospettivo su quasi trecento protesi, il sistema con TC ottiene un allineamento più preciso e un punteggio funzionale migliore a uno e due anni — anche se su un altro punteggio la differenza, pur reale, è così piccola che probabilmente il paziente non la sentirebbe. Il tuo VELYS appartiene alla categoria senza immagini: lo studio non lo nomina direttamente, ma è il primo confronto diretto fra le due filosofie che vale la pena conoscere.\n\nIl lavoro scelto per oggi arriva invece da Pittsburgh, il centro di Volker Musahl che segui come riferimento sul tendine quadricipitale: ventisei anni di dati, quasi ottomila ricostruzioni del legamento crociato anteriore, mostrano che l'uso del tendine quadricipitale è salito con continuità dal 2016 mentre l'hamstring è sceso in modo costante, anno dopo anno. È la tendenza di un solo centro, per quanto ampio, e non tocca in alcun modo la questione del rinforzo laterale che resta al centro della tua tensione più importante — ma conferma che il campo si sta muovendo verso l'innesto che hai già scelto.\n\nRestando sulla chirurgia robotica: una guida tecnica di otto chirurghi europei elenca gli errori più comuni nel posizionamento dei riferimenti anatomici con il sistema VELYS, utile da leggere anche senza numeri da citare; un'altra analisi, su dati di un sistema diverso dal tuo, lega il sovradimensionamento del condilo femorale laterale a un peggior movimento della rotula.\n\nSul fronte dell'osteotomia, due lavori giapponesi e canadesi: il primo mostra che la differenza fra la radiografia in piedi e quella da sdraiati, prima dell'intervento, predice quanto la correzione si scosterà da quella pianificata; il secondo, una revisione di diciassette studi, non trova un beneficio clinico costante nell'aggiungere un trattamento artroscopico di cartilagine o menisco all'osteotomia — un secondo segnale, dopo quello di fine agosto, che la centralizzazione meniscale da sola non risolve il problema dell'estrusione residua.\n\nChiudono la giornata due lavori più rassicuranti: la sutura meniscale funziona bene anche dopo i quarant'anni, anche se il gruppo più adulto studiato era piccolo; e una metanalisi ricorda che un'artroscopia fatta anni prima aumenta il rischio di infezione quando, più avanti, si arriva alla protesi di ginocchio — non per l'anca, ma per il ginocchio sì.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi partiamo dal lavoro con la nota arancione: un confronto fra due robot chirurgici per la protesi di ginocchio."}, {"chi": "B", "t": "Uno vede l'osso con una TC prima di operare, l'altro no, giusto?"}, {"chi": "A", "t": "Esatto. E nel confronto, quello con la TC ottiene un allineamento più preciso e un recupero funzionale migliore, a uno e due anni."}, {"chi": "B", "t": "E il tuo VELYS dove si colloca?"}, {"chi": "A", "t": "Nella categoria senza immagini. Lo studio non lo nomina, ma è il primo confronto diretto fra le due filosofie."}, {"chi": "B", "t": "C'è però una buona notizia sul fronte dell'innesto, oggi."}, {"chi": "A", "t": "Sì, il lavoro scelto per oggi arriva da Pittsburgh, dal gruppo di Volker Musahl: ventisei anni di dati, quasi ottomila ricostruzioni del crociato."}, {"chi": "B", "t": "E il tendine quadricipitale come se la cava?"}, {"chi": "A", "t": "Sale con continuità dal 2016, mentre l'hamstring scende ogni anno. Il campo si muove verso l'innesto che hai già scelto, anche se non dice nulla sul rinforzo laterale."}, {"chi": "B", "t": "Passiamo all'osteotomia: due lavori oggi la toccano."}, {"chi": "A", "t": "Il primo mostra che la differenza fra radiografia in piedi e da sdraiati, prima dell'intervento, aiuta a prevedere quanto la correzione si scosterà da quella pianificata."}, {"chi": "B", "t": "E il secondo?"}, {"chi": "A", "t": "Una revisione di diciassette studi non trova un vantaggio clinico costante nell'aggiungere un trattamento artroscopico all'osteotomia — un secondo segnale che la centralizzazione meniscale, da sola, non basta per l'estrusione."}, {"chi": "B", "t": "E per chiudere?"}, {"chi": "A", "t": "Due segnali pratici: la sutura meniscale funziona bene anche dopo i quarant'anni, e un'artroscopia fatta anni prima al ginocchio pesa un po' di più sul rischio di infezione quando arriva la protesi."}];
